mpz_mul(mrb_state *mrb, mpz_t *ww, mpz_t *u, mpz_t *v)
{
  size_t i,j;
  mp_limb t0,t1,t2,t3;
  mp_limb cc;
  mpz_t w;

  if (uzero(u) || uzero(v)) {
    mpz_set_int(mrb, ww, 0);
    return;
  }
  mpz_init(mrb, &w);
  mpz_realloc(mrb, &w, (size_t)(u->sz + v->sz));
  for (j=0; j < 2*u->sz; j++) {
    cc = (mp_limb)0;
    t3 = hd(u,j);
    for (i=0; i < 2*v->sz; i++) {
      t0 = t3 * hd(v,i);
      t1 = HIGH(t0); t0 = LOW(t0);
      if ((i+j)%2)
        t2 = HIGH(w.p[(i+j)/2]);
      else
        t2 = LOW(w.p[(i+j)/2]);
      t2 += cc;
      if (t2 & HCMASK) {
        cc = 1; t2&=HLMAX;
      }
      else
        cc = 0;
      t2 += t0;
      if (t2 & HCMASK) {
        cc++ ; t2&=HLMAX;
      }
      cc+=t1;
      if ((i+j)%2)
        w.p[(i+j)/2] = LOW(w.p[(i+j)/2]) |
          (t2 << HALFDIGITBITS);
      else
        w.p[(i+j)/2] = (HIGH(w.p[(i+j)/2]) << HALFDIGITBITS) | t2;
    }
    if (cc) {
      if ((j+i)%2)
        w.p[(i+j)/2] += cc << HALFDIGITBITS;
      else
        w.p[(i+j)/2] += cc;
    }
  }
  w.sn = (u->sn) * (v->sn);
  mpz_set(mrb, ww, &w);
  mpz_clear(mrb, &w);
}

